/*
 * Held engine parity check: compiles the firmware's C++ engine core natively (double precision)
 * and compares its rendered frames against the browser engine (wled00/data/held/engine.js) over
 * scripted scenarios that exercise every layer and event.
 *
 *   npm run held:parity
 *
 * Needs a host C++ compiler: g++/clang++ on PATH, or MSVC (found through vswhere on Windows).
 * Exits 0 on match, 1 on mismatch, 2 if no compiler was found.
 */
'use strict';
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { execFileSync, spawnSync } = require('node:child_process');
const HeldEngine = require('../../wled00/data/held/engine.js');

const SRC = path.join(__dirname, 'parity_main.cpp');
const TOL = 1e-4;

function which(cmd) {
  const r = spawnSync(process.platform === 'win32' ? 'where' : 'which', [cmd], { encoding: 'utf8' });
  return r.status === 0 ? r.stdout.split(/\r?\n/)[0].trim() : null;
}

function compile(outDir) {
  const exe = path.join(outDir, process.platform === 'win32' ? 'held_parity.exe' : 'held_parity');
  for (const cxx of ['g++', 'clang++']) {
    if (!which(cxx)) continue;
    execFileSync(cxx, ['-O2', '-std=c++17', '-DHELD_REAL=double', '-o', exe, SRC], { stdio: 'inherit' });
    return exe;
  }
  if (process.platform === 'win32') {
    const vswhere = path.join(process.env['ProgramFiles(x86)'] || 'C:\\Program Files (x86)', 'Microsoft Visual Studio', 'Installer', 'vswhere.exe');
    if (fs.existsSync(vswhere)) {
      const inst = execFileSync(vswhere, ['-latest', '-products', '*', '-requires', 'Microsoft.VisualStudio.Component.VC.Tools.x86.x64', '-property', 'installationPath'], { encoding: 'utf8' }).trim();
      const vcvars = inst && path.join(inst, 'VC', 'Auxiliary', 'Build', 'vcvars64.bat');
      if (vcvars && fs.existsSync(vcvars)) {
        const bat = path.join(outDir, 'build.bat');
        fs.writeFileSync(bat, `@echo off\r\ncall "${vcvars}" >nul\r\ncd /d "${outDir}"\r\ncl /nologo /O2 /EHsc /std:c++17 /DHELD_REAL=double /Fe"${exe}" "${SRC}" >build.log\r\n`);
        const r = spawnSync('cmd.exe', ['/d', '/c', bat], { encoding: 'utf8' });
        if (r.status !== 0) {
          console.error(fs.readFileSync(path.join(outDir, 'build.log'), 'utf8'));
          throw new Error('MSVC build failed');
        }
        return exe;
      }
    }
  }
  return null;
}

// ---- scenarios: [setup commands, timeline of [time, command]]
const FPS = 40;
const SCENARIOS = [
  {
    name: 'two strips, default params, full piece cycle',
    seconds: 45,
    setup: [
      'strips 2',
      'strip 0 leds 120', 'strip 0 origin 10',
      'strip 1 leds 90', 'strip 1 origin 45', 'strip 1 reps 2', 'strip 1 mirror 1'
    ],
    timeline: [
      [2, 'pieces 1'], [5, 'pieces 3'], [8, 'pieces 7'], [10, 'pieces 3'], [12, 'pieces 63'],
      [20, 'pieces 31'], [22, 'pieces 63'], [36, 'trigger pieceIn'], [37, 'trigger pieceOut']
    ]
  },
  {
    name: 'one strip, alternate shapes/blends/directions',
    seconds: 25,
    setup: [
      'strips 1', 'strip 0 leds 150', 'strip 0 origin 70.5', 'strip 0 reps 3', 'strip 0 mirror 0',
      'param heartbeat shape 1 1', 'param heartbeat direction 1 1', 'param heartbeat pulseWidth 7 14',
      'param heartbeat blend 1 1', 'param ambient blend 0 0', 'param ambient noiseOctaves 3 3',
      'param pieceIn blend 2 2', 'param pieceIn direction 2 2', 'param pieceIn numPulses 3 8',
      'param pieceOut flickerCount 12 12', 'param allIn holdDuration 0.5 0.5', 'param allIn beatCount 3 3',
      'param global levelSmoothing 0 0'
    ],
    timeline: [
      [1, 'pieces 3'], [2, 'trigger pieceIn'], [3, 'trigger pieceOut'], [4, 'trigger allIn'],
      [6, 'param heartbeat shape 2 2'], [9, 'trigger allIn'], [10, 'cancel allIn'], [12, 'pieces 0'], [14, 'pieces 63']
    ]
  },
  {
    name: 'expressions, noise pan, release grace',
    seconds: 30,
    setup: [
      'strips 2', 'strip 0 leds 120', 'strip 0 origin 7', 'strip 1 leds 64', 'strip 1 reps 2',
      'param ambient noisePan -4 -4',
      'expr heartbeat bpm (pieces, t) => 50 + 10 * wave(t / 3)',
      'expr heartbeat pulseSpeed (n, time) => { let base = lerp(12, 24, n / 5); const wob = 2 * sin(time * PI); return base + wob; }',
      'expr ambient noiseAmount 0.3 + 0.2 * noise(t) // comment',
      'expr ambient twinkleSize (pieces, t) => clamp(min(3, pieces) + max(0.5, mod(t, 2)) * (t > 3 && t < 9 ? 2 : 1) + (!(pieces > 2) || 0.5), 1, 20)',
      'expr pieceIn width (p, t, et) => 4 + et * 6',
      'expr pieceIn numPulses pieces + 1',
      'expr pieceOut flickerHigh 1 + rnd(t * 10) * 2 ** 1',
      'expr allIn convergeFlicker Math.abs(square(t, 0.3) - triangle(t) * 0.5)',
      'expr allIn beatDecay x => atan2(1, 2) + smoothstep(0, 16, et) * 4 + sign(-3) + round(2.5) + floor(-0.5) + fract(1.25) + exp(0) + log(E) + sqrt(4) + pow(2, 3) / 8 + trunc(1.7) + ceil(0.2) + cos(0) - tan(0) + asin(0) + acos(1) + atan(0) + tri(0.5) - 3'
    ],
    timeline: [
      [1, 'pieces 3'], [2, 'pieces 63'], [4, 'pieces 31'], [6, 'pieces 63'], [14, 'pieces 15'], [15, 'pieces 63'],
      [20, 'trigger pieceIn'], [21, 'pieces 1']
    ]
  }
];

function runJs(sc) {
  const e = new HeldEngine();
  const strips = [];
  const params = {};
  const frames = [];
  const apply = (cmd) => {
    const p = cmd.split(/\s+/);
    switch (p[0]) {
      case 'strips': while (strips.length < +p[1]) strips.push({}); strips.length = +p[1]; e.setStrips(strips.map((s, i) => Object.assign(HeldEngine.SCHEMA.defaultStrip(i), s))); break;
      case 'strip': strips[+p[1]][p[2]] = +p[3]; e.setStrips(strips.map((s, i) => Object.assign(HeldEngine.SCHEMA.defaultStrip(i), s))); break;
      case 'expr': { const src = cmd.split(/\s+/).slice(3).join(' '); e.setParams({ [p[1]]: { [p[2]]: src } }); if (e.exprErrors[p[1] + '.' + p[2]]) throw new Error('JS rejected ' + cmd); break; }
      case 'param': (params[p[1]] = params[p[1]] || {})[p[2]] = [+p[3], +p[4]]; e.setParams({ [p[1]]: { [p[2]]: [+p[3], +p[4]] } }); break;
      case 'pieces': e.setPieces(+p[1]); break;
      case 'trigger': e.trigger(p[1]); break;
      case 'cancel': e.cancel(p[1]); break;
    }
  };
  sc.setup.forEach(apply);
  let ti = 0;
  const lines = [...sc.setup];
  const nFrames = sc.seconds * FPS;
  for (let f = 0; f < nFrames; f++) {
    const t = f / FPS;
    while (ti < sc.timeline.length && sc.timeline[ti][0] <= t) { apply(sc.timeline[ti][1]); lines.push(sc.timeline[ti][1]); ti++; }
    e.tick(1 / FPS); lines.push(`tick ${1 / FPS}`);
    if (f % 2) continue;
    lines.push('render');
    for (let s = 0; s < e.strips.length; s++) {
      const buf = new Float64Array(3 * e.strips[s].leds);
      e.render(s, buf);
      frames.push({ f, s, data: buf });
    }
  }
  return { frames, script: lines.join('\n') + '\n' };
}

function main() {
  const outDir = fs.mkdtempSync(path.join(os.tmpdir(), 'held-parity-'));
  const exe = compile(outDir);
  if (!exe) { console.log('held parity: no host C++ compiler found (g++, clang++ or MSVC) - skipped'); process.exit(2); }
  let ok = true;
  for (const sc of SCENARIOS) {
    const js = runJs(sc);
    const r = spawnSync(exe, [], { input: js.script, encoding: 'utf8', maxBuffer: 1 << 28 });
    if (r.status !== 0) throw new Error('native run failed: ' + r.stderr);
    const rows = r.stdout.trim().split('\n');
    if (rows.length !== js.frames.length) { console.log(`✗ ${sc.name}: frame count ${rows.length} vs ${js.frames.length}`); ok = false; continue; }
    let worst = 0, bad = 0, firstBad = null, total = 0;
    rows.forEach((row, n) => {
      const nat = row.split(' ').map(Number), fr = js.frames[n];
      if (nat.length !== fr.data.length) { bad++; if (!firstBad) firstBad = `frame ${fr.f} strip ${fr.s}: length ${nat.length} vs ${fr.data.length}`; return; }
      for (let j = 0; j < nat.length; j++) {
        const d = Math.abs(nat[j] - fr.data[j]);
        total++;
        if (d > worst) worst = d;
        if (d > TOL) { bad++; if (!firstBad) firstBad = `t=${(fr.f / FPS).toFixed(3)}s strip ${fr.s} led ${Math.floor(j / 3)} ch ${j % 3}: native ${nat[j]} js ${fr.data[j]}`; }
      }
    });
    if (bad) { ok = false; console.log(`✗ ${sc.name}: ${bad}/${total} values differ (max ${worst.toExponential(2)}); first: ${firstBad}`); }
    else console.log(`✓ ${sc.name}: ${rows.length} strip-frames match (max diff ${worst.toExponential(2)})`);
  }
  fs.rmSync(outDir, { recursive: true, force: true });
  process.exit(ok ? 0 : 1);
}

main();
// AI: end
